# Add chronological routes without duplicating canonical transactions.
def _modern_extend(story_id, event_ids, coverage, end_year=None):
    st = next(s for s in stories if s['id'] == story_id)
    event_by_id = {t['id']: t for t in transactions}
    st['transactions'] = sorted(set(st['transactions'] + event_ids.split()), key=lambda tid: (event_by_id[tid]['date'], event_by_id[tid]['order'], tid))
    st['cutoff'] = max(event_by_id[tid]['date'] for tid in st['transactions'])
    st['year'] = min(int(event_by_id[tid]['date'][:4]) for tid in st['transactions'])
    st['endYear'] = end_year or int(st['cutoff'][:4])
    st['coverage'] = coverage

_boston_extensions = 'irving-boston sexton-draft mitchell-cleveland tatum-obligation-rolls langford-draft white-boston wesley-draft'
for _sid in ('brooklyn', 'garnett'):
    if any(s['id'] == _sid for s in stories):
        _modern_extend(_sid, _boston_extensions,
            'Follows the Brooklyn picks to Young, Brown, the Tatum trade-down, Sexton’s Donovan Mitchell package, and Langford’s Derrick White package through September 3, 2022. White’s 2022 first becomes Blake Wesley. Other player moves, later swap amendments and future picks are untraced.')
